INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT159-S1-Q23$batch12$, 159, 1, 23, $batch12$Parallel$batch12$, $batch12$During last year’s flu season no one who was vaccinated contracted the flu. This year every student at South High School has been vaccinated. So this flu season none of the students at South High School will contract the flu.$batch12$, $batch12$Which one of the following arguments is most similar in its reasoning to the argument above?$batch12$, $batch12$A$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$No camper who used insect repellent last month was disturbed by mosquitoes. Since everyone in our campsite has applied insect repellent tonight, none of us will be disturbed by mosquitoes tonight.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$Last year, Marie purchased a car that had been well maintained. Since Marie will certainly continue to maintain the car this year, the car is unlikely to have mechanical problems this year.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$Last year, no student with perfect attendance failed a class, and all students in advanced history had perfect attendance. So no student in advanced history last year failed the class.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$All the fruit we purchased yesterday was fresh. All the fruit we bought yesterday is in the refrigerator. Therefore, all the fruit in the refrigerator is fresh.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$No sparrow eats seeds with hard shells. All seeds of this tree have hard shells. So no sparrow will eat the seeds of this tree.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$No South High students will catch the flu this season.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Last season, no one vaccinated caught the flu. This year every South High student is vaccinated.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Recipe: in a past period, no one who did X got Y. Now everyone in a group did X. So no one in that group will get Y in the new period.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Past: none who did X got Y. Now: all of a group did X. So none will get Y.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Last month no camper with repellent was bothered. Everyone at our site applied repellent tonight, so no one will be bothered. Same recipe.$batch12$), ($batch12$B$batch12$, $batch12$This is about one car and says "unlikely." No past "none who did X" rule.$batch12$), ($batch12$C$batch12$, $batch12$Everything is in the same past period. No prediction about a new one.$batch12$), ($batch12$D$batch12$, $batch12$This is an "all" chain about fruit. No past and present.$batch12$), ($batch12$E$batch12$, $batch12$This is a timeless rule about sparrows. No past period.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT159-S1-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
